    """SW_CORE_BRANCH represents subnet 10.0.0.8/30."""
    return tgraph.check_subnet("SW_CORE_BRANCH", "10.0.0.8/30")


def _check_chain(tgraph, chain, constraint_id, statement):
    """Check that each consecutive pair in the chain has a link."""
    issues = []
    for i in range(len(chain) - 1):
        src, dst = chain[i], chain[i + 1]
        links = tgraph.links(between=[src, dst])
        if not links:
            issues.append({
                "message": f"Missing link between {src} and {dst}.",
                "severity": "error",
                "location": f"links.{src}-{dst}",
                "details": {
                    "constraint_id": constraint_id,
                    "fact_kind": "logical.topology.chain",
                    "statement": statement,
                    "issue_kind": "logical.topology.chain",
                    "repair_target": "graph",
                    "source": src,
                    "target": dst,
                },
            })
    return issues


def check_lc9(tgraph):
    """Explicit chain WEB -> SW_DMZ -> R_CORE."""
    return _check_chain(tgraph, ["WEB", "SW_DMZ", "R_CORE"], "lc9",
                        "explicit chain WEB -> SW_DMZ -> R_CORE.")


def check_lc10(tgraph):
    """Explicit chain PC1 -> SW_OFFICE -> R_CORE."""
    return _check_chain(tgraph, ["PC1", "SW_OFFICE", "R_CORE"], "lc10",
                        "explicit chain PC1 -> SW_OFFICE -> R_CORE.")


def check_lc11(tgraph):
    """Explicit chain PC2 -> SW_OFFICE -> R_CORE."""
    return _check_chain(tgraph, ["PC2", "SW_OFFICE", "R_CORE"], "lc11",
                        "explicit chain PC2 -> SW_OFFICE -> R_CORE.")


def check_lc12(tgraph):
    """Explicit chain PLC1 -> SW_OT -> R_CORE."""
    return _check_chain(tgraph, ["PLC1", "SW_OT", "R_CORE"], "lc12",
                        "explicit chain PLC1 -> SW_OT -> R_CORE.")


def check_lc13(tgraph):
    """Explicit chain ADMIN -> SW_MGMT -> R_CORE."""
    return _check_chain(tgraph, ["ADMIN", "SW_MGMT", "R_CORE"], "lc13",
                        "explicit chain ADMIN -> SW_MGMT -> R_CORE.")


def check_lc14(tgraph):
    """Explicit chain R_CORE -> SW_CORE_FW -> FIREWALL."""
    return _check_chain(tgraph, ["R_CORE", "SW_CORE_FW", "FIREWALL"], "lc14",
                        "explicit chain R_CORE -> SW_CORE_FW -> FIREWALL.")


def check_lc15(tgraph):
    """Explicit chain FIREWALL -> SW_FW_INET -> INTERNET."""
    return _check_chain(tgraph, ["FIREWALL", "SW_FW_INET", "INTERNET"], "lc15",
                        "explicit chain FIREWALL -> SW_FW_INET -> INTERNET.")


def check_lc16(tgraph):
    """Explicit chain R_CORE -> SW_CORE_BRANCH -> R_BRANCH -> SW_BRANCH -> BPC1."""
    return _check_chain(tgraph, ["R_CORE", "SW_CORE_BRANCH", "R_BRANCH", "SW_BRANCH", "BPC1"], "lc16",
                        "explicit chain R_CORE -> SW_CORE_BRANCH -> R_BRANCH -> SW_BRANCH -> BPC1.")


def check_lc17(tgraph):
    """All router ports and FIREWALL/INTERNET interfaces must be assigned fixed IPv4 addresses."""
    issues = []
    for node_id in ["R_CORE", "R_BRANCH", "FIREWALL", "INTERNET"]:
        node = tgraph.get_node(node_id)
        if node is None:
            issues.append({
                "message": f"Node {node_id} does not exist.",
                "severity": "error",
                "location": f"nodes.{node_id}",
                "details": {
                    "issue_kind": "logical.addressing.interface",
                    "constraint_id": "lc17",
                    "repair_target": "graph",
                    "node": node_id,
                },
            })
            continue
        ports = node.get("ports", [])
        if not ports:
            issues.append({
                "message": f"Node {node_id} has no ports to assign IP addresses.",
                "severity": "error",
                "location": f"nodes.{node_id}.ports",
                "details": {
                    "issue_kind": "logical.addressing.interface",
                    "constraint_id": "lc17",
                    "repair_target": "graph",
                    "node": node_id,
                },
            })
            continue
        for port in ports:
            ip = port.get("ip")
            if not ip:
                issues.append({
                    "message": f"Port {port.get('name', 'unnamed')} on {node_id} has no IPv4 address.",
                    "severity": "error",
                    "location": f"nodes.{node_id}.ports.{port.get('name', 'unnamed')}",
                    "details": {
                        "issue_kind": "logical.addressing.interface",
                        "constraint_id": "lc17",
                        "repair_target": "graph",
                        "node": node_id,
                        "port": port.get("name", "unnamed"),
                    },
                })
    return issues if issues else []

