support_files.physical/checkpoints.py:
def check_pc1(tgraph):
    """FIREWALL requires firewall appliance image capability."""
    node = tgraph.node("FIREWALL") or {}
    image = node.get("image") or {}
    expected_image_ids = ["pfsense", "opnsense"]
    actual_image_id = image.get("id")
    if actual_image_id not in expected_image_ids:
        return {
            "message": "FIREWALL must use an image with firewall appliance capability.",
            "severity": "error",
            "location": "nodes.FIREWALL.image",
            "details": {
                "issue_kind": "physical.image.capability.unsatisfied",
                "constraint_id": "pc1",
                "repair_target": "node.FIREWALL.image",
                "expected_image_ids": expected_image_ids,
                "actual_image_id": actual_image_id,
            },
        }
    return []


def check_pc2(tgraph):
    """INTERNET requires external network simulator image capability."""
    node = tgraph.node("INTERNET") or {}
    image = node.get("image") or {}
    expected_image_ids = ["linux_internet_gateway"]
    actual_image_id = image.get("id")
    if actual_image_id not in expected_image_ids:
        return {
            "message": "INTERNET must use an image with external network simulator capability.",
            "severity": "error",
            "location": "nodes.INTERNET.image",
            "details": {
                "issue_kind": "physical.image.capability.unsatisfied",
                "constraint_id": "pc2",
                "repair_target": "node.INTERNET.image",
                "expected_image_ids": expected_image_ids,
                "actual_image_id": actual_image_id,
            },
        }
    return []

